const id = target.id;
const queryDateControl = control.querySelector(`.aras-singular[data-id="${id}"]`);
const wndRect = aras.uiGetElementCoordinates(queryDateControl);
const dialogOptions = {
	withTime: true,
	left: wndRect.left - wndRect.screenLeft,
	top: wndRect.top - wndRect.screenTop
};
const topWindow = aras.getMostTopWindowWithAras(window);
const dialogPromise = topWindow.ArasCore.Dialogs.datePicker(dialogOptions);
const { result } = await dialogPromise;
if (result === undefined) {
	return;
}
const queryDate = result || null;
const { updateQueryDate } = options.getActions();
updateQueryDate(queryDate);
